<?php
declare(strict_types=1);
require __DIR__.'/auth.php';requireAdmin();require ROOT_PATH.'/includes/comments.php';ensureCommentsTable();$db=database();
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$status=in_array($_POST['status']??'', ['approved','spam','trash'],true)?$_POST['status']:'pending';$db->prepare('UPDATE wts_blog_comments SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);header('Location:'.url('admin/comments.php?updated=1'));exit;}
$comments=$db?$db->query("SELECT * FROM wts_blog_comments WHERE status<>'trash' ORDER BY status='pending' DESC,created_at DESC")->fetchAll():[];$adminTitle='Comment moderation';$currentAdminPage='comments';require __DIR__.'/_header.php';?>
<header class="admin-title"><div><p class="kicker">Reader discussion</p><h1>Comment moderation</h1><p>Approve thoughtful responses before they appear publicly, or mark unwanted submissions as spam.</p></div></header><?php if(isset($_GET['updated'])):?><p class="notice success">Comment updated.</p><?php endif;?><section class="admin-panel comment-admin-list"><?php foreach($comments as $comment):?><article><header><strong><?=e($comment['name'])?></strong><span><?=e($comment['email'])?> · <?=e($comment['post_slug'])?> · <?=e($comment['created_at'])?></span><em><?=e($comment['status'])?></em></header><p><?=nl2br(e($comment['body']))?></p><form method="post"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="id" value="<?= (int)$comment['id']?>"><button name="status" value="approved">Approve</button><button name="status" value="spam">Spam</button><button name="status" value="trash">Delete</button></form></article><?php endforeach;?><?php if(!$comments):?><p>No comments to moderate.</p><?php endif;?></section><?php require __DIR__.'/_footer.php'; ?>
